import java.util.HashMap;
import java.util.Map;

public class Main {
    static byte[] data;
    static int pos = 0;

    static boolean skipSpace() {
        while (pos < data.length && (data[pos] & 0xff) <= ' ') pos++;
        return pos < data.length;
    }

    static String token() {
        skipSpace();
        int s = pos;
        while (pos < data.length && (data[pos] & 0xff) > ' ') pos++;
        return new String(data, s, pos - s, java.nio.charset.StandardCharsets.UTF_8);
    }

    static long num() {
        skipSpace();
        boolean neg = false;
        if (pos < data.length && (data[pos] == '-' || data[pos] == '+')) neg = data[pos++] == '-';
        long v = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') v = v * 10 + (data[pos++] - '0');
        return neg ? -v : v;
    }

    public static void main(String[] args) throws Exception {
        data = System.in.readAllBytes();
        int n = (int) num();
        long sum = 0;
        HashMap<Long, Integer> count = new HashMap<>();
        for (int i = 0; i < n; i++) {
            long x = num();
            sum += x;
            count.merge(x, 1, Integer::sum);
        }
        long mean = Math.floorDiv(sum, (long) n);  // floor, also for negative sums
        long best = 0, mode = 0;
        for (Map.Entry<Long, Integer> e : count.entrySet()) {
            long x = e.getKey(), c = e.getValue();
            if (c > best || (c == best && x < mode)) {  // ties: smallest value
                best = c;
                mode = x;
            }
        }
        System.out.println(mean + " " + mode);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := num()
	var sum int64
	count := map[int64]int64{}
	for i := int64(0); i < n; i++ {
		x := num()
		sum += x
		count[x]++
	}
	// Floor division (rounds toward negative infinity for negative sums).
	mean := sum / n
	if sum%n != 0 && (sum < 0) != (n < 0) {
		mean--
	}
	var best, mode int64
	for x, c := range count {
		if c > best || (c == best && x < mode) { // ties: smallest value
			best, mode = c, x
		}
	}
	fmt.Println(mean, mode)
}
